#include <iostream>
#include <optional>
#include <string>
using namespace std;

optional<int> parse_int(const string& s) {
    try {
        return stoi(s);
    } catch (...) {
        return nullopt;          // 明确表达「失败」而非返回 -1 之类的魔数
    }
}

int main() {
    for (const string s : {"42", "abc"}) {
        auto r = parse_int(s);
        if (r) {
            cout << "\"" << s << "\" -> 解析成功: " << *r << "\n";
        } else {
            cout << "\"" << s << "\" -> 解析失败，value_or 兜底: " << r.value_or(-1) << "\n";
        }
    }
    optional<string> o;
    cout << boolalpha << "默认构造的 optional<string> has_value = " << o.has_value() << "\n";
    cout << "对比：返回指针要管所有权，抛异常有开销，optional 把「无值」写进类型系统\n";
}
